import {objects,price,stateLabel,total,euro,marketLink} from './data.js';
import {initializeCamera} from './camera.js';
const $=s=>document.querySelector(s);let selected=0,focused=null,mode='explore',showPrices=true,placement=null,placementPromise=null,scanTimer=null,scanStep=0,toastTimer;
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
const icons={bed:'M3 17V9m18 8V9M3 14h18v5M5 14V8h14v6M7 11h3m4 0h3',chair:'M5 11v7h14v-7M7 12V5h10v7M5 14h14M7 18v3m10-3v3',lamp:'M7 10l2-7h6l2 7H7m5 0v10m-4 1h8',table:'M3 9h18M6 9v11m12-11v11M3 6h18v3H3z',unknown:'M9 7a3 3 0 116 0c0 2-3 2-3 5m0 4v1M4 4h16v16H4z'};
function renderObject(){const card=$('#object-card');card.hidden=mode==='place'||!showPrices;const o=objects.find(o=>o.id===focused);card.classList.toggle('empty',!o);if(!o){card.innerHTML='<div class="demo-focus">DEIN BLICK ENTSCHEIDET</div><div class="focus-empty">Nimm ein Möbelstück ins Fadenkreuz. Passende Preisvergleiche erscheinen hier.</div>';return;}selected=objects.indexOf(o);card.innerHTML=`<div class="demo-focus">IM FOKUS / ${o.quantity>1?o.quantity+' IM RAUM':'1 OBJEKT'}</div><span class="confidence ${o.state}">${o.state==='safe'?'✓':o.state==='probable'?'≈':'?'} ${stateLabel(o)}</span><h3>${o.name}</h3><p>${o.detail}</p><div class="object-price">${price(o)}</div><p>${o.min===null?'Kein belastbarer Vergleichswert':`Angebotsspanne${o.quantity>1?' pro Stück':''} · ähnliche Produkte`}</p><p class="reason">${o.reason}</p>${o.comparables?.length?`<div class="source-count">${o.comparables.length} recherchierte Vergleiche · Ähnlichkeit begrenzt</div><button class="sources-button" id="show-sources">Angebote & Preisgrundlage ↗</button>`:'<div class="source-count">Nicht in der bewerteten Teilsumme enthalten</div>'}`;$('#show-sources')?.addEventListener('click',()=>openSources(o));$('#object-counter').textContent=`${String(selected+1).padStart(2,'0')} / ${String(objects.length).padStart(2,'0')}`;renderInventory();}
function openSources(o){const dialog=$('#source-dialog');$('#source-title').textContent=o.name+' · Preisvergleich';$('#source-body').innerHTML=`<p>${o.reason}</p><div class="source-method">${o.method??'Die Spanne zeigt den niedrigsten und höchsten Angebotspreis der unten verlinkten Vergleichsprodukte.'}${o.quantity>1?` Im Raum werden ${o.quantity} Stück berücksichtigt.`:''}</div><ul class="source-list">${(o.comparables??[]).map(c=>`<li><a href="${c.url}" target="_blank" rel="noopener noreferrer">${c.title} ↗</a><strong>${euro(c.price)}${c.negotiable?' VB':''}</strong><p>${c.similarity}</p><p>${c.date} · ${c.location??'Deutschland'} · Kleinanzeigen</p><p>${c.availability??'Angebotsseite bei Recherche erreichbar; Verfügbarkeit kann sich ändern.'}</p></li>`).join('')}</ul><p class="source-caution">Recherche: 22.09.2026. Angebotspreise, keine nachgewiesenen Verkaufspreise. Keine exakten Herstellerzuordnungen, keine automatische Marktbeobachtung. Maße, Zustand und Lieferumfang der Vergleichsangebote können abweichen.</p>`;dialog.showModal();}
function selectObject(index){if(!Number.isInteger(index)||index<0||index>=objects.length)throw new Error('Unbekanntes Objekt.');selected=index;camera.focus(index);$('#object-counter').textContent=`${String(index+1).padStart(2,'0')} / 06`;renderInventory();}
function renderInventory(){const filter=$('#confidence-filter').value;const rows=objects.filter(o=>filter==='all'||o.state===filter);$('#inventory-rows').innerHTML=rows.map(o=>`<div class="inventory-entry"><button class="inventory-row ${objects[selected].id===o.id?'selected':''}" data-row="${objects.indexOf(o)}" aria-label="${o.name}: im Raum ansehen"><span><span class="object-symbol"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[o.icon]??icons.unknown}"/></svg></span><span>${o.name}${o.quantity>1?' × '+o.quantity:''}<span class="confidence ${o.state}">${stateLabel(o)}</span></span></span><span>${price(o)}${o.quantity>1&&o.min!==null?'<small class="per-item"> pro Stück</small>':''}</span><span class="row-platform">${o.comparables.length?'Kleinanzeigen':'Vergleich offen'}<span>↗</span></span></button>${o.comparables.length?`<button class="row-source" data-source="${o.id}">${o.comparables.length} ${o.comparables.length===1?'Vergleichsangebot':'Vergleichsangebote'} & Herleitung ansehen ↗</button>`:''}</div>`).join('');const t=total(rows);$('#inventory-summary').textContent=`${rows.length} Objektgruppen · ${t.count} Stück bewertet · ${filter==='all'?'Bewertete Teilsumme':'Auswahl'} ${euro(t.min)}–${euro(t.max)}`;$('#inventory-rows').querySelectorAll('[data-row]').forEach(b=>b.addEventListener('click',async()=>{await setMode('value');selectObject(Number(b.dataset.row));$('#demo').scrollIntoView({behavior:'smooth'});}));$('#inventory-rows').querySelectorAll('[data-source]').forEach(b=>b.addEventListener('click',()=>openSources(objects.find(o=>o.id===b.dataset.source))));}
function renderTotals(){const t=total(objects),safe=total(objects.filter(o=>o.state==='safe')),probable=total(objects.filter(o=>o.state==='probable'));$('#total-price').textContent=`${t.min}–${t.max} €`;$('.quick-stats').innerHTML=`<div><span class="stat-number">360°</span><span>Fester Standpunkt. Freier Blick.</span></div><div><span class="stat-number">6 <small>Gruppen</small></span><span>Manuell im Modell zugeordnet</span></div><div><span class="stat-number">${t.min}–${t.max} <small>€</small></span><span>Bewerteter Teil des Raums</span></div><div class="stat-note">Ein neuer Blick auf Dinge,<br>die schon da sind.</div>`;$('.value-bars').innerHTML=`<div><span>Kategorie bestätigt</span><b>${safe.min}–${safe.max} €</b></div><div class="bar"><span style="width:${t.max?safe.max/t.max*100:0}%"></span></div><div><span>Wahrscheinliche Zuordnung</span><b>${probable.count?probable.min+'–'+probable.max+' €':'Bewertung offen'}</b></div><div class="bar probable"><span style="width:${t.max?probable.max/t.max*100:0}%"></span></div>`;$('.valuation-foot').innerHTML=`<span>${t.count} Stück bewertet</span><span>${objects.filter(o=>o.min===null).length} Gruppen offen</span>`;$('.valuation-note').textContent='Teilwert der belegten Vergleichskategorien. Zwei Betten zählen doppelt. Unbewertete Möbel und weitere Gegenstände sind nicht enthalten. Der vollständige Raumwert bleibt offen.';}
async function setMode(next){if(!['explore','value','place'].includes(next))throw new Error('Unbekannte Ansicht.');mode=next;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});const placing=mode==='place';$('#sketchfab').inert=placing;$('#sketchfab').setAttribute('aria-hidden',String(placing));$('#value-strip').hidden=mode!=='value';$('#viewer').classList.toggle('placing',placing);$('#placement-stage').hidden=!placing;$('.viewer-top').hidden=placing;$('#viewer-hint').hidden=placing;$('#mode-note').textContent=placing?'ROOM-ONLY · Draufsicht · Flur ausgeblendet':'Fester Standpunkt · Preise folgen dem tatsächlich anvisierten Modellteil';$('#previous-object').disabled=placing;$('#next-object').disabled=placing;$('#object-counter').hidden=placing;camera?.setActive(!placing);renderObject();
 if(placing&&!placement){if(!placementPromise){$('#placement-stage').innerHTML='<div class="viewer-loader">Möbel-Demo wird geladen …</div>';placementPromise=import('./placement.js').then(m=>{placement=m.createPlacement($('#placement-stage'),notify);return placement;}).catch(()=>{$('#placement-stage').innerHTML='<div class="viewer-error"><strong>Möbel-Demo konnte nicht geladen werden.</strong><p>Bitte prüfe die Verbindung und versuche es erneut.</p><button class="button" id="retry-placement">Erneut laden</button></div>';$('#retry-placement').addEventListener('click',()=>{placementPromise=null;setMode('place');});});}await placementPromise;}placement?.setActive?.(mode==='place');return{mode};}
function startScan(){if(scanTimer)return;if(scanStep===4){$('#werte').scrollIntoView({behavior:'smooth'});return;}scanStep=0;$('#start-scan').disabled=true;$('#ablauf').classList.add('scan-running');const stages=[['Raumgeometrie erfassen …','Die Simulation veranschaulicht das Zusammensetzen von Wänden und Ecken.'],['Objektgruppen zuordnen …','Die Beispieldaten unterscheiden bestätigte Kategorien, Vermutungen und offene Identitäten.'],['Vergleichsangebote einbeziehen …','Das Beispiel verwendet die hinterlegten, recherchierten Angebote. Keine Live-Abfrage.'],['Dein Demo-Raum ist bereit.','Die Objektübersicht zeigt belegte Teilwerte und offene Bewertungen.']];function advance(){const s=stages[scanStep];$('#scan-title').textContent=s[0];$('#scan-description').textContent=s[1];$('#scan-progress').style.width=`${(scanStep+1)*25}%`;$('#scan-percent').textContent=`${(scanStep+1)*25} % · simuliert`;scanStep++;if(scanStep===4){clearInterval(scanTimer);scanTimer=null;$('#start-scan').disabled=false;$('#start-scan').innerHTML='Ergebnis ansehen <span>↗</span>';$('#ablauf').classList.remove('scan-running');notify('Demo-Scan abgeschlossen. Die Übersicht ist bereit.');}}advance();scanTimer=setInterval(advance,1500);}
const camera=initializeCamera(objects,id=>{focused=id;renderObject();},state=>{if(state==='ready'){$('#viewer-loader').hidden=true;$('#viewer').dataset.cameraReady='true';$('#viewer-hint').textContent='Nach oben ziehen = Blick nach oben · Standpunkt bleibt fixiert';}else{$('#viewer-loader').innerHTML=`${state==='slow'?'Der Raum braucht länger zum Laden.':'3D-Raum nicht erreichbar.'} <a href="https://sketchfab.com/models/f5d2584af20c4c778e22544c1c1334c6/embed" target="_blank" rel="noopener noreferrer">Auf Sketchfab öffnen ↗</a>`;}});
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));$('#confidence-filter').addEventListener('change',renderInventory);$('#previous-object').addEventListener('click',()=>selectObject((selected+5)%6));$('#next-object').addEventListener('click',()=>selectObject((selected+1)%6));$('#hotspot-toggle').addEventListener('click',()=>{showPrices=!showPrices;$('#hotspot-toggle').textContent=`◉ Preise ${showPrices?'an':'aus'}`;$('#hotspot-toggle').setAttribute('aria-pressed',String(showPrices));renderObject();});$('#start-scan').addEventListener('click',startScan);$('#close-sources').addEventListener('click',()=>$('#source-dialog').close());$('#source-dialog').addEventListener('click',e=>{if(e.target===$('#source-dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close();}});
for(const id of ['open-placement','preview-play','watch-placement'])$('#'+id).addEventListener('click',async()=>{const ready=setMode('place');$('#demo').scrollIntoView({behavior:'smooth'});await ready;if(id==='watch-placement')placement?.play();});
$('#value-strip').innerHTML=objects.slice(0,3).map((o,i)=>`<button data-value-object="${i}">${o.name} · ${price(o)}</button>`).join('');$('#value-strip').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>selectObject(Number(b.dataset.valueObject))));renderObject();renderInventory();renderTotals();
document.querySelectorAll('p').forEach(p=>{if(p.textContent.includes('Im separaten Beispielraum'))p.textContent='In derselben Raumidee zeigt die Platzierungsansicht den Hotelraum von oben; der Flur ist ausgeblendet. Sessel und Tisch lassen sich verschieben, drehen und umfärben.';if(p.textContent.includes('Die Möbel-Demo nutzt einen separaten Beispielraum'))p.textContent=p.textContent.replace('Die Möbel-Demo nutzt einen separaten Beispielraum','Die Möbel-Demo zeigt dieselbe Raumidee von oben und blendet den Flur aus');});
const overviewMarkup=`<section class="product-overview wrap" id="overview" aria-labelledby="overview-title"><div class="overview-lead"><div><div class="eyebrow"><span class="eyebrow-rule"></span> RAUMIO IN EINEM BLICK</div><h2 id="overview-title">Aus deinem Raum<br><span>wird eine Entscheidung.</span></h2></div><p>RAUMIO verbindet Raumscan, Objekterkennung und Marktvergleich in einem verständlichen Ablauf. Du siehst, was in deinem Zuhause steckt, welchen Wert es ungefähr hat und wie neue Möbel darin wirken könnten.</p></div><div class="overview-grid"><article><span class="overview-index">01</span><div class="overview-icon">⌗</div><h3>Erfassen</h3><p>Mit iPhone oder iPad den Raum aus mehreren Blickwinkeln aufnehmen und als begehbares 3D-Modell aufbauen.</p><span>RAUMGEOMETRIE · OBJEKTE</span></article><article><span class="overview-index">02</span><div class="overview-icon">€</div><h3>Verstehen</h3><p>Gegenstände zuordnen, Sicherheit sichtbar machen und ähnliche Gebrauchtangebote mit ihrer Herleitung zeigen.</p><span>ERKENNUNG · WERT</span></article><article><span class="overview-index">03</span><div class="overview-icon">＋</div><h3>Weiterdenken</h3><p>Neue Möbel im gleichen Raum ausprobieren, Positionen vergleichen und später direkt passende Produkte finden.</p><span>PLATZIEREN · ENTSCHEIDEN</span></article></div><div class="overview-foot"><span>Heute als Konzeptdemo erlebbar</span><a href="#demo">Jetzt den Raum öffnen <b>↗</b></a></div></section>`;
const heroElement=document.querySelector('.hero');if(heroElement&&!document.querySelector('#overview'))heroElement.insertAdjacentHTML('afterend',overviewMarkup);const mainNav=document.querySelector('.header nav');if(mainNav&&!mainNav.querySelector('[href="#overview"]'))mainNav.insertAdjacentHTML('afterbegin','<a href="#overview">Produkt</a>');
const sceneLabel=document.querySelector('.scene-label');if(sceneLabel)sceneLabel.textContent='ROOM VIEW · RAUMIO';const viewerFrame=document.querySelector('#sketchfab');if(viewerFrame)viewerFrame.title='RAUMIO — interaktiver 3D-Raum';const scenePreview=document.querySelector('.scene-preview');if(scenePreview)scenePreview.alt='Vorschau des interaktiven RAUMIO-Raums';
const viewerBrand=document.querySelector('#viewer');if(viewerBrand&&!viewerBrand.querySelector('.viewer-brand'))viewerBrand.insertAdjacentHTML('afterbegin','<div class="viewer-brand" aria-hidden="true"><span>RAUMIO</span><small>ROOM VIEW · INTERACTIVE SPACE</small></div>');
const context=document.modelContext;const lifecycle=new AbortController();if(context?.registerTool){for(const tool of [{name:'read_room_demo',description:'Read the room comparison valuation and current mode. This is a researched asking-price sample, not a live appraisal.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return{mode,focused,valuation:total(objects),completeRoomValue:false,dataType:'asking-price-comparisons'};}},{name:'focus_room_object',description:'Rotate the view toward a curated furniture anchor from the fixed camera position. Does not buy or sell anything.',inputSchema:{type:'object',properties:{objectId:{type:'string',enum:objects.map(o=>o.id)}},required:['objectId'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input||typeof input.objectId!=='string'||Object.keys(input).some(k=>k!=='objectId'))throw new Error('Ungültige Auswahl');const index=objects.findIndex(o=>o.id===input.objectId);if(index<0)throw new Error('Unbekanntes Objekt');await setMode('value');selected=index;const actualFocus=await camera.focusAndWait(index);$('#demo').scrollIntoView({behavior:'instant'});return{targetObject:objects[index].id,focusedObject:actualFocus,price:actualFocus?price(objects.find(o=>o.id===actualFocus)):'Kein Treffer',cameraPositionFixed:true};}}]){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
window.addEventListener('pagehide',()=>{clearInterval(scanTimer);clearTimeout(toastTimer);placement?.dispose();camera.dispose();lifecycle.abort();});
